import { HttpClient } from '@angular/common/http';
import { Injectable } from '@angular/core';

@Injectable({
  providedIn: 'root'
})
export class WeatherService {
  private apiUrl = 'http://127.0.0.1:5000/api/weather'; // URL de ton backend Flask
  constructor(private http: HttpClient) { }

  getweather(city: string, units: string) {
    return this.http.get('https://api.openweathermap.org/data/2.5/weather?q=Tunis&appid=e7c54ea8408b03d38d6de1ac149cb9a9&units=imperial');
  }

}
